//! Origin, provenance, tracking state, reasons and feature availability.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Where data came from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum Origin {
    /// A physical device, now.
    Live,
    /// Generated by the simulator.
    Simulated,
    /// Prerecorded data replayed as if it were a device.
    Fixture,
}

/// Whether the engine is processing live sources or replaying a session.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum EngineMode {
    Live,
    Replay,
}

/// How a value was obtained. A value computed from several inputs takes the weakest.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum Provenance {
    /// Observed directly in the frame it is reported in.
    Measured,
    /// Computed from sensor data through a valid calibration.
    Derived,
    /// Filled in by a model, prior or heuristic.
    Inferred,
    /// No value can be given.
    Unavailable,
}

/// Shared state vocabulary for devices, streams, segments and the whole system.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum TrackingState {
    /// Known or configured, no transport link.
    Disconnected,
    /// Link up, data arriving, not yet usable.
    Acquiring,
    /// Valid data at the expected rate and quality.
    Tracking,
    /// Data arriving but below a threshold.
    Degraded,
    /// Cannot be used until someone acts.
    Unavailable,
}

/// Machine-readable explanation of a degraded, unavailable or inferred condition.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct Reason {
    /// Stable code, e.g. `segment_not_observed`.
    pub code: String,
    /// The device, segment or feature the reason is about, if any.
    pub subject: Option<String>,
    /// Message written for the user.
    pub message: String,
}

/// Overall tracking quality of one frame.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct TrackingQuality {
    pub state: TrackingState,
    /// Segments whose rotation is measured or derived.
    pub observed_segments: u32,
    pub total_segments: u32,
    pub reasons: Vec<Reason>,
}

/// A capability the engine reports as available or not.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum FeatureId {
    SegmentOrientation,
    SkeletonPose,
    JointAngles,
    RootPosition,
    #[serde(rename = "landmarks_2d")]
    Landmarks2d,
    #[serde(rename = "landmarks_3d_triangulated")]
    Landmarks3dTriangulated,
    CameraImuFusion,
    GroundContact,
    Recording,
    Playback,
}

/// Availability of a feature.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum FeatureState {
    Available,
    Degraded,
    Unavailable,
}

/// Availability of one feature, evaluated by the engine's rule table.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
pub struct FeatureStatus {
    pub id: FeatureId,
    pub state: FeatureState,
    pub reasons: Vec<Reason>,
}
